const H = params.height;
const stalkH = H * 0.56;
const stalkR = H * 0.18;
const capR = H * 0.43;
const capY = H * 0.62;
const wallMaterial = { preset: 'wood', color: '#d8b47b', roughness: 0.9, flatShading: true };
const capMaterial = { preset: 'plastic', color: params.capColor, roughness: 0.72, flatShading: true };
const creamMaterial = { preset: 'plastic', color: '#f3e4c0', roughness: 0.82, flatShading: true };
const darkWoodMaterial = { preset: 'wood', color: '#563426', roughness: 0.88 };
const trimMaterial = { preset: 'wood', color: '#8a5934', roughness: 0.82 };
const windowMaterial = { preset: 'glass', color: '#ffd36a', emissive: '#f5a63b', emissiveIntensity: 1.4, opacity: 0.88, roughness: 0.18 };
const stoneMaterial = { preset: 'stone', color: '#77716a', roughness: 0.95, flatShading: true };
const chimneyMaterial = { preset: 'brick', color: '#755047', roughness: 0.94, flatShading: true };
const stalkProfile = [[0, 0], [stalkR * 0.78, 0], [stalkR * 0.95, H * 0.08], [stalkR * 0.82, H * 0.25], [stalkR, H * 0.43], [stalkR * 0.84, stalkH], [0, stalkH]];
const stalk = api.lathe(stalkProfile, 18);
stalk.vertexColor((x, y, z) => api.mix('#ead09b', '#bd8d5b', 0.2 + 0.12 * api.noise3(x * 3, y * 2, z * 3)));
api.add(stalk, wallMaterial);
const cap = api.sphere(1, 3).scale(capR, H * 0.25, capR).translate(0, capY, 0);
cap.vertexColor((x, y, z) => api.mix(params.capColor, '#711a27', Math.max(0, Math.min(0.32, (capY - y) / (H * 0.55)))));
api.add(cap, capMaterial);
api.add(api.cylinder(capR * 0.86, capR * 0.86, H * 0.035, 24).translate(0, capY - H * 0.105, 0), creamMaterial);
const spotX = [0, -0.23, 0.24, 0.13, -0.14, 0.31, -0.32, -0.3, 0.33];
const spotZ = [0, 0.1, 0.08, 0.27, -0.29, -0.2, -0.17, 0.25, 0.23];
const spotY = [0.245, 0.18, 0.17, 0.15, 0.15, 0.11, 0.1, 0.09, 0.08];
const spotS = [0.13, 0.105, 0.095, 0.09, 0.105, 0.075, 0.08, 0.07, 0.065];
for (let i = 0; i < spotX.length; i++) {
  const spot = api.sphere(spotS[i] * H, 1).scale(1, 0.28, 1).translate(spotX[i] * H, capY + spotY[i] * H, spotZ[i] * H);
  api.add(spot, creamMaterial);
}
const doorW = H * 0.15;
const doorH = H * 0.25;
const frontZ = stalkR * 0.86;
api.add(api.box(doorW, doorH * 0.68, H * 0.025).translate(0, doorH * 0.34, frontZ), darkWoodMaterial);
api.add(api.sphere(doorW * 0.5, 2).scale(1, 1, 0.18).translate(0, doorH * 0.68, frontZ), darkWoodMaterial);
api.add(api.torus(doorW * 0.54, H * 0.012).translate(0, doorH * 0.68, frontZ + H * 0.018), trimMaterial);
api.add(api.sphere(H * 0.018, 1).translate(doorW * 0.3, doorH * 0.38, frontZ + H * 0.025), { preset: 'metal', color: '#d9a441', metalness: 0.75, roughness: 0.28 });
for (let i = 0; i < 3; i++) {
  const stepW = doorW * (1.35 + i * 0.24);
  api.add(api.box(stepW, H * 0.025, H * 0.1).translate(0, H * (0.012 + i * 0.022), frontZ + H * (0.07 + i * 0.018)), stoneMaterial);
}
const windowAngles = [90, 180, 270];
for (let i = 0; i < windowAngles.length; i++) {
  const angle = windowAngles[i];
  const radians = angle * Math.PI / 180;
  const wx = Math.sin(radians) * stalkR * 0.91;
  const wz = Math.cos(radians) * stalkR * 0.91;
  const wy = H * (0.25 + (i % 2) * 0.07);
  api.add(api.sphere(H * 0.07, 2).scale(1, 1, 0.16).rotate(0, angle, 0).translate(wx, wy, wz), windowMaterial);
  api.add(api.torus(H * 0.075, H * 0.012).rotate(0, angle, 0).translate(wx, wy, wz), trimMaterial);
  api.add(api.box(H * 0.012, H * 0.13, H * 0.012).rotate(0, angle, 0).translate(wx, wy, wz), trimMaterial);
  api.add(api.box(H * 0.13, H * 0.012, H * 0.012).rotate(0, angle, 0).translate(wx, wy, wz), trimMaterial);
}
const chimneyX = H * 0.19;
const chimneyZ = -H * 0.11;
api.add(api.cylinder(H * 0.047, H * 0.06, H * 0.29, 8).rotate(0, 0, -8).translate(chimneyX, capY + H * 0.16, chimneyZ), chimneyMaterial);
api.add(api.cylinder(H * 0.069, H * 0.069, H * 0.035, 8).rotate(0, 0, -8).translate(chimneyX + H * 0.018, capY + H * 0.305, chimneyZ), stoneMaterial);
for (let i = 0; i < 5; i++) {
  const angle = i * Math.PI * 2 / 5;
  const rockRadius = H * (0.025 + 0.008 * (i % 2));
  api.add(api.icosphereRock(rockRadius, 0.35).translate(Math.cos(angle) * stalkR * 0.94, H * 0.025, Math.sin(angle) * stalkR * 0.94), stoneMaterial);
}
api.collider({ kind: 'cylinder', radius: stalkR, halfHeight: stalkH * 0.5, offset: [0, stalkH * 0.5, 0] });
api.collider({ kind: 'cylinder', radius: capR * 0.88, halfHeight: H * 0.11, offset: [0, capY, 0] });
return api.build();
